private.candidate_write_blocked:
select p_owner_id is null or exists(select 1 from public.data_requests d
  where d.user_id=p_owner_id and d.kind='deletion'
    and d.status is distinct from 'failed' and d.status is distinct from 'cancelled');

private.serialize_deletion_request:
begin
  if tg_op='UPDATE' and (new.id,new.user_id,new.organization_id,new.kind)
    is distinct from (old.id,old.user_id,old.organization_id,old.kind) then
    raise exception 'PRIVACY_REQUEST_IDENTITY' using errcode='23514'; end if;
  if new.kind='deletion' then
    if current_setting('transaction_isolation') not in ('read committed','read uncommitted') then
      raise exception 'PRIVACY_ISOLATION_UNSUPPORTED' using errcode='25000'; end if;
    if not private.try_lock_candidate_owners(array[new.user_id]) then
      raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03'; end if;
  elsif new.kind='export' and (tg_op='INSERT'
    or (new.result_manifest is not null and new.result_manifest<>'null'::jsonb
      and new.result_manifest is distinct from old.result_manifest)) then
    -- New intake/personal-data copies are work; failure bookkeeping and manifest
    -- erasure remain available after deletion, including the privacy worker.
    if not private.try_candidate_privacy_write(new.user_id) then
      raise exception 'CANDIDATE_WRITE_BLOCKED' using errcode='42501'; end if;
  end if;
  return new;
end;

public.prepare_deletion_request:
declare
  request_row public.data_requests%rowtype;
  storage_objects jsonb;
begin
  select * into request_row
  from public.data_requests
  where id = p_request_id
    and kind = 'deletion'
    and status = 'processing'
    and lease_owner = p_worker_id
  for update;
  if not found then
    raise exception 'privacy deletion request is not owned' using errcode = '42501';
  end if;

  select plan.storage_objects into storage_objects
  from private.privacy_deletion_plans plan
  where plan.request_id = request_row.id;

  if not found then
    select coalesce(jsonb_agg(jsonb_build_object(
      'storageKey', storage_key,
      'checksum', checksum,
      'bytes', bytes
    )), '[]'::jsonb)
    into storage_objects
    from public.resume_versions
    where owner_id = request_row.user_id;

    insert into private.privacy_deletion_plans (request_id, storage_objects)
    values (request_row.id, storage_objects);
  end if;

  -- Candidate rows and the durable object plan commit atomically. A retry can
  -- therefore continue deleting the same objects after database rows are gone.
  perform private.retire_initial_feedback_publications(request_row.user_id,null,request_row.id,null);
  delete from public.analyses where owner_id = request_row.user_id;
  delete from public.jobs where owner_id = request_row.user_id;
  delete from public.resumes where owner_id = request_row.user_id;
  delete from public.consents where user_id = request_row.user_id;
  delete from public.memberships where user_id = request_row.user_id;
  delete from public.profiles where id = request_row.user_id;

  update public.privacy_request_steps
  set status = 'completed', completed_at = timezone('utc', now())
  where request_id = request_row.id and step_key = 'database';

  return jsonb_build_object(
    'storageObjects', storage_objects,
    'databaseDeletedAt', timezone('utc', now())
  );
end;

