  if p_policy->>'version' is distinct from 'initial-feedback-publication/1.0.0' or p_policy->>'provider' is distinct from 'openai'
    or (p_policy->>'model') collate "C" !~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,99}$'
    or p_policy->>'promptVersion' is distinct from 'qualitative-cited-prose/3.0.0'
    or (p_policy->>'sha256') collate "C" !~ '^[a-f0-9]{64}$'
    or p_policy->>'supportVersion' is distinct from 'qualitative-content-support/1.0.0'
    or p_policy->>'supportSha256' is distinct from '230f22333dd468f3bf78395b118330ec1ff78de18be9da5349356e84d0f6bd13'
    or p_policy->>'planVersion' is distinct from 'initial-feedback-plan-policy/1.0.0'
    or p_policy->>'planSha256' is distinct from '972b648ccc90b29c0c88fc504ac2746ab1489e17f05cfd2048cb487a2b38cc48'
    or p_policy->>'writingSupportPolicyVersion' is distinct from 'legacy-source-transforms/1.0.4'
    or p_policy->'scoringInputProfile' is distinct from $scoring${"schemaVersion":"legacy-scoring-readiness/1.0.0","profileVersion":"legacy-scoring-profile/1.0.0","checkerSha256":"56a92f65d533a2f1b053078dbb372b1271728224e5df1c74b201b4cffb21a8d3","readerSha256":"2ea3c5071d8d56e421a37053127dea08fe8eb08ce91e4de9f5c3b4c4b1172ccf","finishSha256":"5db61206ed04f32af7052fce2d64e2ccf414d6fea13645f58eecf67f616b61a2","contextSha256":"d64ba9ac11ba732c983cd195cd7d83fba878e67f4ae0bffc8b6e166a600a8bd9","exportSha256":"e4c17997fdbec81d931e4838b3522c6c7d3c861b0bfa07b6fb3ab5ece160f0a2","metadataSha256":"f18e6abfd698c4dbf4f7f6040fb577b2e49e78e4125bfd9d31e8166d0e678da8"}$scoring$::jsonb
    or p_policy->'planProfile' is distinct from $plan${"schemaVersion":"initial-feedback-plan-readiness/1.0.0","profileVersion":"initial-feedback-plan-profile/1.0.0","policyVersion":"initial-feedback-plan-policy/1.0.0","policySha256":"972b648ccc90b29c0c88fc504ac2746ab1489e17f05cfd2048cb487a2b38cc48","checkerSha256":"c5d8c0e8e5ac52c8b06a4fad5ea78f6fe6e42297bbbfd51cd2779243c8418b36","rendererSha256":"c8bc131aacc7f9ddd8e30dcca8f5f429e78ee84180e5dd4542254883001cedc6","metadataSha256":"3c133694d11334e9430821945c94782b562ab1efb3f26bb8d4e7a9f2699369c5"}$plan$::jsonb then return false;end if;
  if jsonb_typeof(p_policy->'maxOutputTokens') is distinct from 'number' or (p_policy->>'maxOutputTokens') collate "C" !~ '^[1-9][0-9]{0,9}$'
    or jsonb_typeof(p_policy->'attemptLimit') is distinct from 'number' or (p_policy->>'attemptLimit') collate "C" !~ '^[1-3]$' then return false;end if;
  if (p_policy->>'maxOutputTokens')::numeric not between 256 and 8000 then return false;end if;
  if p_policy->'budgetPolicyVersion'<>'null'::jsonb and (jsonb_typeof(p_policy->'budgetPolicyVersion') is distinct from 'string'
    or (p_policy->>'budgetPolicyVersion') collate "C" !~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,99}$') then return false;end if;
  return p_policy->>'sha256'=private.ifo_sha(private.ifo_policy_frame(p_policy));
end;

private.ifo_selected_policy:
declare sel private.initial_feedback_selections%rowtype;pol jsonb;
begin
  if private.ifo_keys(p_selector,array['version','sha256']) is not true
    or jsonb_typeof(p_selector->'version') is distinct from 'string'
    or jsonb_typeof(p_selector->'sha256') is distinct from 'string'
    or (p_selector->>'sha256') collate "C" !~ '^[a-f0-9]{64}$' then perform private.ifo_fail('invalid');end if;
  select * into sel from private.initial_feedback_selections where organization_id=p_org and enabled for share skip locked;
  if not found then perform private.ifo_fail('unavailable');end if;
  if sel.policy_version is distinct from p_selector->>'version' or sel.policy_sha256 is distinct from p_selector->>'sha256' then perform private.ifo_fail('stale');end if;
  select descriptor into pol from private.initial_feedback_policies where version=sel.policy_version and sha256=sel.policy_sha256 for share skip locked;
  if not found or private.ifo_policy_valid(pol) is not true then perform private.ifo_fail('unavailable');end if;
  return pol;
end;

